 "يمكن للمدير العام تغيير النصوص الظاهرة وتشغيل الأقسام أو إيقافها وضبط صلاحيات العرض والتعديل. مفاتيح النظام والروابط الداخلية والحسابات لا تتغير.": {
  "en": "The general manager can change displayed text, enable or disable sections, and set viewing and editing permissions. System keys, internal links and calculations stay unchanged.",
  "hi": "महाप्रबंधक प्रदर्शित पाठ बदल सकता है, अनुभाग चालू या बंद कर सकता है और देखने तथा संपादन की अनुमतियाँ तय कर सकता है। प्रणाली कुंजियाँ, आंतरिक लिंक और गणनाएँ अपरिवर्तित रहती हैं।",
  "ur": "جنرل منیجر دکھائی جانے والی عبارت بدل سکتا، حصے کھول یا بند کرسکتا اور دیکھنے و ترمیم کی اجازتیں مقرر کرسکتا ہے۔ نظام کی کلیدیں، اندرونی روابط اور حساب تبدیل نہیں ہوتے۔",
  "ml": "ജനറൽ മാനേജർക്ക് പ്രദർശിപ്പിക്കുന്ന വാചകം മാറ്റാനും വിഭാഗങ്ങൾ പ്രവർത്തനക്ഷമമാക്കാനോ നിർത്താനോ കാണൽ-തിരുത്തൽ അനുമതികൾ നിശ്ചയിക്കാനോ കഴിയും. സിസ്റ്റം കീകളും ആന്തരിക ലിങ്കുകളും കണക്കുകളും മാറില്ല."
 },
