  "ml": "രേഖകൾ തുറന്ന ഫയലുമായി ബന്ധിപ്പിച്ചിരിക്കുന്നു. വിഭാഗം തിരഞ്ഞെടുത്ത് പേജുകളുടെ ചിത്രമെടുക്കുക അല്ലെങ്കിൽ ഫയൽ അപ്‌ലോഡ് ചെയ്യുക."
