 "الأساسي والبدلات وبيانات الموظف محفوظة كما كانت عند تجهيز هذا الراتب. تعديل ملف الموظف لا يغيّر الرواتب السابقة. بند السلفة في المستحقات يخص سلفة جديدة تُصرف مع الراتب؛ قسط السلفة السابقة في الخصومات. لا تكرر السلفة نفسها في سجل السلف. تُثبت في الرصيد عند إثبات الصرف فقط.": {
  "en": "Basic pay, allowances and employee details are frozen when this payroll is prepared. Editing the employee file does not change earlier payrolls. An advance under entitlements is a new advance paid with salary; an earlier advance installment is a deduction. Do not record the same advance twice in the advances register. It enters the balance only when payment is confirmed.",
  "hi": "यह वेतन तैयार करते समय मूल वेतन, भत्ते और कर्मचारी विवरण सुरक्षित रखे जाते हैं। कर्मचारी फ़ाइल बदलने से पुराने वेतन नहीं बदलते। देय मदों में अग्रिम नया अग्रिम है जो वेतन के साथ दिया जाता है; पुराने अग्रिम की किस्त कटौती है। उसी अग्रिम को अग्रिम रजिस्टर में दोबारा दर्ज न करें। भुगतान की पुष्टि पर ही वह शेष में जुड़ता है।",
  "ur": "یہ تنخواہ تیار ہوتے وقت بنیادی تنخواہ، الاؤنس اور ملازم کی تفصیلات محفوظ ہوجاتی ہیں۔ ملازم کی فائل بدلنے سے سابقہ تنخواہیں نہیں بدلتیں۔ مستحقات میں پیشگی رقم نئی رقم ہے جو تنخواہ کے ساتھ ادا ہوتی ہے؛ سابقہ پیشگی رقم کی قسط کٹوتی ہے۔ ایک ہی پیشگی رقم رجسٹر میں دوبارہ درج نہ کریں۔ ادائیگی کی تصدیق پر ہی وہ بیلنس میں شامل ہوتی ہے۔",
  "ml": "ഈ ശമ്പളം തയ്യാറാക്കുമ്പോഴുള്ള അടിസ്ഥാന ശമ്പളം, അലവൻസുകൾ, ജീവനക്കാരന്റെ വിവരങ്ങൾ എന്നിവ നിലനിർത്തും. ജീവനക്കാരന്റെ ഫയൽ തിരുത്തുന്നത് പഴയ ശമ്പളങ്ങളെ മാറ്റില്ല. ലഭിക്കാനുള്ള ഇനങ്ങളിലെ മുൻകൂർ തുക ശമ്പളത്തോടൊപ്പം നൽകുന്ന പുതിയ തുകയാണ്; പഴയ മുൻകൂർ തുകയുടെ ഗഡു കിഴിവിലാണ്. അതേ മുൻകൂർ തുക രജിസ്റ്ററിൽ വീണ്ടും രേഖപ്പെടുത്തരുത്. പേയ്‌മെന്റ് സ്ഥിരീകരിക്കുമ്പോൾ മാത്രമേ ബാലൻസിൽ ഉൾപ്പെടുത്തൂ."
 },
