 "الصلاحيات تخص الحسابات النشطة. تُطبق أيضاً قيود القسم والدور من مركز تحكم المدير. الوصول لملف مرتبط بعدة عقارات يتطلب التصريح بجميع عقاراته. الاعتمادان يحتاجان حسابين مختلفين.": {
  "en": "Permissions apply to active accounts, subject to section and role limits in the manager control center. A file linked to multiple properties requires access to all of them. The two approvals require different accounts.",
  "hi": "अनुमतियाँ सक्रिय खातों पर लागू होती हैं और प्रबंधक केंद्र की अनुभाग तथा भूमिका सीमाओं के अधीन हैं। कई संपत्तियों से जुड़ी फ़ाइल के लिए सभी की पहुँच आवश्यक है। दोनों अनुमोदन अलग खातों से होने चाहिए।",
  "ur": "اجازتیں فعال اکاؤنٹس پر لاگو ہوتی ہیں اور منیجر مرکز کی حصے اور کردار کی حدود بھی نافذ ہیں۔ متعدد جائیدادوں سے منسلک فائل کے لیے سب کی اجازت ضروری ہے۔ دونوں منظوریوں کے لیے الگ اکاؤنٹس درکار ہیں۔",
  "ml": "അനുമതികൾ സജീവ അക്കൗണ്ടുകൾക്ക് ബാധകമാണ്; മാനേജർ നിയന്ത്രണ കേന്ദ്രത്തിലെ വിഭാഗ-റോൾ പരിധികളും ബാധകമാണ്. ഒന്നിലധികം വസ്തുക്കളുമായി ബന്ധിപ്പിച്ച ഫയലിന് അവയെല്ലാം കാണാനുള്ള അനുമതി വേണം. രണ്ട് അംഗീകാരങ്ങൾക്കും വ്യത്യസ്ത അക്കൗണ്ടുകൾ വേണം."
 },
