  "ml": "കണക്കുകൾ ലഭിച്ച ഡാറ്റയ്ക്ക് മാത്രമാണ്; സമ്പൂർണ അക്കൗണ്ടിംഗ് സ്റ്റേറ്റ്മെന്റോ ശുദ്ധ ലാഭമോ അല്ല."
