  "hi": "Excel में सभी पृष्ठों पर खोज, स्थिति और प्रकार से मेल खाते परिणाम, फ़िल्टर और डेटा प्राप्ति समय शामिल हैं। डाउनलोड से पहले रिकॉर्ड और अनुमतियाँ फिर जाँची जाती हैं।",
  "ur": "Excel میں تمام صفحات پر تلاش، حالت اور قسم سے مطابق نتائج، فلٹر اور ڈیٹا حاصل کرنے کا وقت شامل ہیں۔ ڈاؤن لوڈ سے پہلے ریکارڈ اور اجازتیں دوبارہ جانچی جاتی ہیں۔",
  "ml": "എല്ലാ പേജുകളിലുമുള്ള തിരയൽ, നില, തരം എന്നിവയുമായി പൊരുത്തപ്പെടുന്ന ഫലങ്ങളും ഫിൽറ്ററുകളും ലഭ്യമാക്കിയ സമയവും Excel-ൽ ഉൾപ്പെടും. ഡൗൺലോഡിനുമുമ്പ് രേഖകളും അനുമതികളും വീണ്ടും പരിശോധിക്കും."
