  "ml": "രേഖ ചേർക്കാൻ ക്യാമറയോ ഫയലോ തിരഞ്ഞെടുത്ത് വസ്തു, വാടകക്കാരൻ അല്ലെങ്കിൽ കരാർ നിശ്ചയിച്ച് സൂക്ഷിക്കുക. പകർപ്പ് അതേ രേഖയുടെ ഡോക്യുമെന്റുകളിൽ കാണാം."
