  "en": "Only the general manager manages these options. Owner reports respect the saved property scope. Linking a recipient to an owner account limits the report to properties authorized for that account.",
  "hi": "केवल महाप्रबंधक इन विकल्पों का प्रबंधन करता है। मालिक की रिपोर्ट सहेजे गए संपत्ति दायरे का पालन करती है। प्राप्तकर्ता को मालिक खाते से जोड़ने पर रिपोर्ट उसी खाते की अधिकृत संपत्तियों तक सीमित रहती है।",
