  "en": "In-platform circulars for selected employees. Read acknowledgment is linked to the account and circular version; it is not an electronic signature or external message delivery. This section shows your latest 100 accessible records.",
  "hi": "चयनित कर्मचारियों के लिए मंच के अंदर परिपत्र। पढ़ने की पुष्टि खाते और परिपत्र संस्करण से जुड़ी है; यह इलेक्ट्रॉनिक हस्ताक्षर या बाहरी संदेश की सुपुर्दगी नहीं है। यह अनुभाग आपके लिए उपलब्ध नवीनतम 100 रिकॉर्ड दिखाता है।",
