  "ml": "തിരഞ്ഞെടുത്ത ജീവനക്കാർക്കുള്ള പ്ലാറ്റ്ഫോമിലെ സർക്കുലറുകൾ. വായന സ്ഥിരീകരണം അക്കൗണ്ടുമായും സർക്കുലർ പതിപ്പുമായും ബന്ധിപ്പിച്ചിരിക്കുന്നു; ഇത് ഇലക്ട്രോണിക് ഒപ്പോ പുറമേ സന്ദേശം ലഭിച്ചതിന്റെ തെളിവോ അല്ല. നിങ്ങൾക്ക് ലഭ്യമായ ഏറ്റവും പുതിയ 100 രേഖകളാണ് ഇവിടെ കാണിക്കുന്നത്."
